async function familyStatusRowsV221(collection,rows,statusField,statuses){
  if(!state.user&&(state.parentFamily||state.parentStudent)&&typeof window.queryFamilyRecordsV221==='function'){
    const all=await window.queryFamilyRecordsV221(collection,rows,{mode:'full'});
    return all.filter(x=>statuses.includes(String(x?.[statusField]||'')));
  }
  const rid=String(state.parentFamily?.responsavelId||familyKey(rows?.[0]||{})||''),specs=[],add=(field,value,array=false)=>{if(value&&!specs.some(x=>x.field===field&&String(x.value)===String(value)))specs.push({field,value,array})};
  if(rid){add('responsavelFinanceiroId',rid);add('responsavelId',rid)}for(const a of rows||[]){if(a?.id){add('alunoId',a.id);}}
  const out=[];try{for(const sp of specs){let cursor=null;while(true){let q=db.collection(collection);q=sp.array?q.where(sp.field,'array-contains',sp.value):q.where(sp.field,'==',sp.value);q=q.where(statusField,'in',statuses).limit(60);if(cursor)q=q.startAfter(cursor);const snap=await q.get();out.push(...snap.docs.map(d=>({id:d.id,...d.data(),_collection:collection})));if(snap.size<60)break;cursor=snap.docs[snap.docs.length-1]}}return dedupe(out)}catch(indexError){console.warn('familyStatusRowsV221 fallback',collection,indexError?.message||indexError);const all=typeof window.queryFamilyRecordsV221==='function'?await window.queryFamilyRecordsV221(collection,rows,{mode:'full'}):await queryByFamily(collection,rows);return all.filter(x=>statuses.includes(String(x?.[statusField]||'')))}}
async function loadParentNoticeFamilyV172(){const host=$('#v151ParentNotice'),rows=parentFamilyStudents();if(!host)return;try{const [payments,orders]=await Promise.all([familyStatusRowsV221('pagamentos_checkout',rows,'status',['preparando_link','aguardando_pagamento','erro_timeout','erro_gerar_link','erro_sem_url','pagamento_localizado_processando','pagamento_localizado_aguardando_processamento']),familyStatusRowsV221('pedidos',rows,'statusPedido',['confirmado','reservado'])]),acc=state.parentFamily?.conta||{},pending=payments.length,deliveries=orders.length,net=typeof netV151==='function'?netV151(acc):Number(acc?.saldoContaCentavos||0),weeklyBlocked=Boolean(acc?.bloqueioSaldoSemanal)&&net<0;host.innerHTML=`${weeklyBlocked?`<button class="alert danger v175-regularize-alert" onclick="openParentPaymentV151()"><strong>Conta bloqueada por pendência — Regularize agora</strong><span>Saldo em aberto de ${fmt(Math.abs(net))}. Pague para liberar a conta automaticamente.</span></button>`:''}${pending?`<button class="alert warn v154-pending-alert" style="margin-top:${weeklyBlocked?8:0}px" onclick="openParentPendingPaymentsV154()"><strong>${pending} pagamento(s) pendente(s).</strong> Toque para abrir.</button>`:''}${deliveries?`<button class="alert v156-program-alert" style="margin-top:${weeklyBlocked||pending?8:0}px" onclick="openParentOrdersV151()"><strong>${deliveries} programação(ões) de lanche ativa(s).</strong><span>Ver pedidos →</span></button>`:''}`;}catch(e){console.warn('parent-notice-v221',e);host.innerHTML=`<div class="alert warn"><strong>Não foi possível atualizar os avisos agora.</strong><br><span class="muted">${esc(e.message||'Falha de consulta.')}</span></div>`}}

