  do{h=await window.loadFamilyHistoryWindowV221('parent_pending_payments','pagamentos_checkout',rows,{orderField:'criadoEm',pageSize:30,reset:reset&&!h});state.v172PendingPayments=h.merged.filter(p=>PENDING_STATUS_V221.has(p.status)).sort((x,y)=>String(y.criadoEm||'').localeCompare(String(x.criadoEm||'')));if(h.done||state.v172PendingPayments.length>=target)break}while(true);
