function plannerLineForStudentV172(student){const selection=window.PiagetOrderPlanner?.getSelection?.();if(!selection?.items?.length||!selection.deliveryCount)throw new Error('Selecione ao menos um dia e adicione um produto.');if(selection.items.some(x=>x.quantity<1||x.quantity>10))throw new Error('A quantidade de cada produto por dia deve ficar entre 1 e 10.');const draft=window.PiagetOrderPlanner.saveDraft(),dates=selection.dates||[...new Set(selection.items.map(x=>x.date))].sort();return{draft,line:{alunoId:student.id,alunoNome:student.nome,turma:student.turma||null,turno:student.turno||null,matricula:student.matricula||null,responsavelFinanceiroId:student.responsavelFinanceiroId||student.contaFinanceiraId||null,tipo:'programacao_lanche',tipoOperacional:'programacao_lanche',nome:'Programação de lanches',categoria:'Cantina',quantidade:1,precoUnitarioCentavos:selection.total,totalCentavos:selection.total,pedido:{modalidade:state.v150OrderMode,itens:selection.items.map(x=>({dataChave:x.date,produtoId:x.productId,quantidade:x.quantity}))},metadados:{modalidade:state.v150OrderMode,quantidadeEntregas:selection.deliveryCount,quantidadeItens:selection.itemCount,primeiraData:dates[0],ultimaData:dates[dates.length-1]},diasResumo:selection.items},selection}}
async function captureParentSnackV172(){const f=state.v172ParentSnack,target=familyStudent(f.ids[f.index],parentFamilyStudents());const {draft,line}=plannerLineForStudentV172(target);f.lines[f.index]=line;f.drafts[f.index]=draft;f.lastStudent=target;if(f.index<f.ids.length-1){const next=familyStudent(f.ids[f.index+1],parentFamilyStudents());f.index++;openModal(`Programação de ${next.nome}`,`<div class="alert"><strong>${esc(target.nome)} já está pronto.</strong><br>Você pode copiar a mesma programação para ${esc(next.nome)} e alterar só o que for diferente.</div><div class="actions" style="margin-top:14px"><button class="btn btn-primary" onclick="launchParentSnackCopyV172(true)">Copiar programação de ${esc(target.nome)}</button><button class="btn btn-outline" onclick="launchParentSnackCopyV172(false)">Montar do zero</button></div>`);return}return reviewParentFamilySnackV172()}
