async function reviewParentFamilySnackV172(){const f=state.v172ParentSnack,primary=buyerPrimary(),acc=await getAccount(primary.id),net=typeof netV151==='function'?netV151(acc):Number(acc.saldoContaCentavos||0),total=f.lines.reduce((s,x)=>s+Number(x.totalCentavos||0),0);state.v172FamilySnackUseBalance=net>0;const grouped=f.lines.map(x=>`<div class="v172-family-review-row">${studentTag(familyStudent(x.alunoId,parentFamilyStudents()))}<div><strong>${x.metadados.quantidadeEntregas} entrega(s)</strong><span>${fmt(x.totalCentavos)}</span></div></div>`).join('');openModal('Revisar lanches da família',`<div class="v172-family-review">${grouped}</div><div class="v150-modal-summary" style="margin-top:12px"><div><span>Total dos lanches</span><strong>${fmt(total)}</strong></div><div><span>Saldo da família</span><strong>${signedV151(net)}</strong></div></div><label class="switch-line" style="margin-top:12px"><div><strong>Usar saldo disponível</strong><div class="muted">O crédito é compartilhado pela família.</div></div><input id="v172FamilyUseBalance" type="checkbox" ${net>0?'checked':'disabled'} onchange="state.v172FamilySnackUseBalance=this.checked"></label><div id="v172FamilySnackStatus" style="margin-top:10px"></div><button id="v172FamilySnackCheckout" class="btn btn-green" style="width:100%;margin-top:12px" onclick="submitParentFamilySnackV172()">Continuar para o pagamento</button>`)}
window.submitParentFamilySnackV172=async function(){const f=state.v172ParentSnack,primary=buyerPrimary(),btn=$('#v172FamilySnackCheckout'),host=$('#v172FamilySnackStatus');if(!f?.lines?.length)return;try{const acc=await getAccount(primary.id);if(state.parentFamily)state.parentFamily.conta=acc;const net=typeof netV151==='function'?netV151(acc):Number(acc.saldoContaCentavos||0),total=f.lines.reduce((s,x)=>s+Number(x.totalCentavos||0),0),use=Boolean(state.v172FamilySnackUseBalance)&&net>0,credit=use?Math.min(Math.max(0,net),total):0,debt=Math.max(0,-net),external=total-credit+debt;let customer=null;if(external>0){customer=await checkoutBuyerStepV157(primary,{amountCentavos:external,description:'Lanches da família'});if(!customer)return}const payload={tipo:'venda_online_secretaria',alunoId:primary.id,alunosIds:f.ids,itens:f.lines,usarSaldo:use,comprador:customer?{nome:customer.name,telefone:customer.phone_number,email:customer.email}:undefined,criadoPorId:'portal_responsavel',criadoPorNome:primary.responsavelFinanceiro||'Responsável',criadoPorPerfil:'responsavel'};if(btn){btn.disabled=true;btn.textContent=external>0?'Preparando pagamento...':'Confirmando...'}const data=await requestCheckoutV154(payload,{button:btn,statusHost:host});if(data.preparando)return;if(data.sem_checkout){state.v172ParentSnack=null;closeModal();toast('Lanches programados.');return renderParentPortal()}if(!data.checkout_url)throw new Error('O link de pagamento ainda não está disponível.');location.href=data.checkout_url}catch(e){if(host)host.innerHTML=`<div class="alert danger">${esc(e.message)}</div>`;else appMessage(e.message)}};

