window.openResponsibleAccessManagerV130=async function(alunoId){
  const a=(state.students||[]).find(x=>String(x.id)===String(alunoId));if(!a)return;
  const rid=familyKey(a);if(!rid)return appMessage('Prepare a base oficial de responsáveis antes de gerenciar este acesso.');
  try{
    const [ac,reqs,links]=await Promise.all([
      db.collection('responsaveis_acesso').doc(rid).get(),
      db.collection('solicitacoes_reset_responsavel').where('responsavelId','==',rid).get(),
      db.collection('reset_senha_responsavel').where('responsavelId','==',rid).get()
    ]);
    const data=ac?.exists?ac.data():null,children=staffFamilyStudents(a),hasPassword=Boolean(data?.senhaHash),active=Boolean(data?.ativo&&hasPassword);
    const status=!hasPassword?'Primeiro acesso pendente':active?'Senha ativa':'Acesso bloqueado';
    openModal('Acesso ao Meu Piaget',`<div class="mini-breakdown"><span><span>Conta familiar</span><strong>${children.length} aluno(s)</strong></span><span><span>Status</span><strong>${status}</strong></span>${data?.ultimoAcessoEm?`<span><span>Último acesso</span><strong>${humanDate(data.ultimoAcessoEm)}</strong></span>`:''}</div><div class="v167-linked-students">${children.map(x=>`<div class="student-row"><div><strong>${esc(x.nome)}</strong><div class="muted">${esc(x.turma||'-')} · ${esc(x.matricula||'-')}</div></div></div>`).join('')}</div><div class="alert" style="margin-top:12px">O login é único para esta família. O comprador de uma operação pode ser outra pessoa.</div><div class="actions" style="margin-top:14px"><button class="btn btn-primary" onclick="generateParentResetLinkV130('${js(alunoId)}')">Gerar link de redefinição</button><button class="btn btn-light" onclick="downloadFirstAccessCardV172('${js(alunoId)}')">Baixar primeiro acesso</button>${hasPassword&&!active?`<button class="btn btn-green" onclick="reactivateFamilyAccessV172('${js(alunoId)}')">Desbloquear acesso</button>`:`<button class="btn btn-red" onclick="blockParentAccessV130('${js(alunoId)}')">Bloquear acesso</button>`}</div><div id="parentResetLinkHostV130" style="margin-top:14px"></div><div class="tiny-v130" style="margin-top:12px">Solicitações históricas: ${reqs.docs.length} · Links gerados: ${links.docs.length}</div>`);
  }catch(e){console.warn('responsible-access-v221',e);appMessage(`Não foi possível carregar o histórico de acesso: ${e.message||'falha de leitura'}`)}
};
