window.renderUsuariosAcessosV130=async function(){if(!['admin','gestao'].includes(state.user?.perfil))return navigate('alunos');try{const users=(typeof window.allCollectionRowsV221==='function'?await window.allCollectionRowsV221('usuarios_acesso',100):(await db.collection('usuarios_acesso').get()).docs.map(d=>({id:d.id,...d.data()}))).sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR'));$('#mainContent').innerHTML=pageHeader('Usuários e acessos','Perfis internos da Equipe Piaget.',`<button class="btn btn-primary" onclick="openUserProfileV130()">Novo perfil</button>`)+`<div class="grid g2"><div class="card"><div class="card-head"><div class="card-title">Equipe interna</div></div><div class="card-body"><div class="alert">Gerencie aqui somente acessos de Gestão, Secretaria e Cantina. O acesso das famílias fica em <strong>Alunos e Contas</strong>.</div><div style="margin-top:12px">${users.map(u=>userRowHtmlV130(u)).join('')||'<div class="empty">Nenhum usuário configurado.</div>'}</div></div></div><div class="card"><div class="card-head"><div class="card-title">Permissões por perfil</div></div><div class="card-body"><div class="perm-grid-v130">${['admin','gestao','secretaria','cantina'].map(p=>`<div class="perm-chip-v130"><strong>${roleLabelV130(p)}</strong><br>${permissionListV166(p).join(', ')}</div>`).join('')}</div></div></div></div>`}catch(e){$('#mainContent').innerHTML=pageHeader('Usuários e acessos','Falha ao carregar perfis internos.')+`<div class="alert danger"><strong>Não foi possível carregar os usuários.</strong><br>${esc(e.message||'Falha de consulta.')}</div><button class="btn btn-primary" onclick="renderUsuariosAcessosV130()">Tentar novamente</button>`}};

